CREATE TABLE public.planipret_ava_sms_pilot (user_id uuid PRIMARY KEY, profile_id uuid NOT NULL, enabled boolean NOT NULL DEFAULT false, activated_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.planipret_ava_sms_pilot TO authenticated; GRANT ALL ON public.planipret_ava_sms_pilot TO service_role; ALTER TABLE public.planipret_ava_sms_pilot ENABLE ROW LEVEL SECURITY; CREATE POLICY pilot_read ON public.planipret_ava_sms_pilot FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.is_planipret_admin(auth.uid())); CREATE TABLE public.planipret_ava_sms_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), message_id uuid NOT NULL UNIQUE, user_id uuid NOT NULL, profile_id uuid NOT NULL, peer text NOT NULL, status text NOT NULL DEFAULT 'processing', proposal jsonb, reply text, reply_claimed_at timestamptz, calendar_claimed_at timestamptz, result jsonb, error_code text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.planipret_ava_sms_jobs TO authenticated; GRANT ALL ON public.planipret_ava_sms_jobs TO service_role; ALTER TABLE public.planipret_ava_sms_jobs ENABLE ROW LEVEL SECURITY; CREATE POLICY job_read ON public.planipret_ava_sms_jobs FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.is_planipret_admin(auth.uid()));